function simplePurifier(
    text,
    bHtml = false,
    bSvg = false,
    bSvgFilters = false
)
{
    return DOMPurify.sanitize(
        sanitizeDom(text)
            .replaceAll('&lt;', '<')
            .replaceAll('&#x3C;', '<')
            .replaceAll('&#60;', '<')
            .replaceAll('&gt;', '>')
            .replaceAll('&#x3E;', '>')
            .replaceAll('&#62;', '>')
            .replaceAll('&amp;', '&')
            .replaceAll('&#38;', '&')
            .replaceAll('&#x26;', '&')
            .replaceAll('&quot;', '"')
            .replaceAll('&#34;;', '"')
            .replaceAll('&#x22;', '"')
            .replaceAll('&#39;', "'"),
        {USE_PROFILES: {html:bHtml, svg:bSvg, svgFilters: bSvgFilters}}
    );
}

