function _makeSetter( property, next ){
	if (property === '__proto__'){
		throw new Error('unable to access __proto__');
	}

	if ( next ){
		return function setter( ctx, value ){
			var t = ctx[property];

			if ( !t ){
				t = ctx[property] = {};
			}

			return next( t, value );
		};
	}else{
		return function( ctx, value ){
			ctx[property] = value;
			return ctx;
		};
	}
}

async function task() {
