function readKey() {
	let length = src[position++]
	if (length >= 0xa0 && length < 0xc0) {
		length = length - 0xa0
		if (srcStringEnd >= position)
			return srcString.slice(position - srcStringStart, (position += length) - srcStringStart)
		else if (!(srcStringEnd == 0 && srcEnd < 180))
			return readFixedString(length)
	} else {
		position--
		return asSafeString(read())
	}
	let key = ((length << 5) ^ (length > 1 ? dataView.getUint16(position) : length > 0 ? src[position] : 0)) & 0xfff
	let entry = keyCache[key]
	let checkPosition = position
	let end = position + length - 3
	let chunk
	let i = 0
	if (entry && entry.bytes == length) {
		while (checkPosition < end) {
			chunk = dataView.getUint32(checkPosition)
			if (chunk != entry[i++]) {
				checkPosition = 0x70000000
				break
			}
			checkPosition += 4
		}
		end += 3
		while (checkPosition < end) {
			chunk = src[checkPosition++]
			if (chunk != entry[i++]) {
				checkPosition = 0x70000000
				break
			}
		}
		if (checkPosition === end) {
			position = checkPosition
			return entry.string
		}
		end -= 3
		checkPosition = position
	}
	entry = []
	keyCache[key] = entry
	entry.bytes = length
	while (checkPosition < end) {
		chunk = dataView.getUint32(checkPosition)
		entry.push(chunk)
		checkPosition += 4
	}
	end += 3
	while (checkPosition < end) {
		chunk = src[checkPosition++]
		entry.push(chunk)
	}
	let string = length < 16 ? shortStringInJS(length) : longStringInJS(length)
	if (string != null)
		return entry.string = string
	return entry.string = readFixedString(length)
}

function submitForm( event ) {
		event.preventDefault();

		const form = event.currentTarget;
		const messageContainer = form.querySelector( '.form-block__message-container' );

		if ( messageContainer ) {
			messageContainer.remove();
		}

		setSubmitMessage( form, 'loading', formBlockData.i18n.isLoading );

		let intervalCount = 0;
		const interval = setInterval( () => {
			intervalCount++;

			if ( intervalCount > 10 ) {
				clearInterval( interval );
			}

			if ( ! formBlockIsValidated ) {
				return;
			}

			clearInterval( interval );
			const formData = new FormData( form );
			const xhr = new XMLHttpRequest();

			formData.set( 'action', 'form-block-submit' )

			xhr.open( 'POST', formBlockData.ajaxUrl, true );
			xhr.send( formData );
			xhr.onreadystatechange = () => {
				if ( xhr.readyState !== 4 ) {
					return;
				}

				if ( xhr.status === 200 ) {
					try {
						const response = JSON.parse( xhr.responseText );

						if ( response.success ) {
							form.reset();
							setSubmitMessage( form, 'success', formBlockData.i18n.requestSuccess );
						}
						else if ( response?.data?.message ) {
							setSubmitMessage( form, 'error', response?.data?.message );
						}
						else {
							setSubmitMessage( form, 'error', formBlockData.i18n.backendError );
						}
					}
					catch ( error ) {
						setSubmitMessage( form, 'error', formBlockData.i18n.backendError );
						console.error( error );
					}
				}
				else {
					setSubmitMessage( form, 'error', formBlockData.i18n.requestError );
					console.error( xhr.responseText );
				}
			}
		}, 50 );
	}

function parseURLParams(
        url: URL,
        dontParse: boolean = false,
        source: string = 'hash'): Object {
    const paramStr = source === 'search' ? url.search : url.hash;
    const params = {};
    const paramParts = (paramStr && paramStr.substr(1).split('&')) || [];

    if (source === 'hash' && paramParts.length === 1) {
        const firstParam = paramParts[0];

        if (firstParam.startsWith('/') && firstParam.split('&').length === 1) {
            return params;
        }
    }

    paramParts.forEach(part => {
        const param = part.split('=');
        const key = param[0];

        if (!key) {
            return;
        }

        let value;

        try {
            value = param[1];

            if (!dontParse) {
                const decoded = decodeURIComponent(value).replace(/\\&/, '&');

                value = decoded === 'undefined' ? undefined : JSON.parse(decoded);
            }
        } catch (e) {
            reportError(
                e, `Failed to parse URL parameter value: ${String(value)}`);

            return;
        }
        params[key] = value;
    });

    return params;
}

