    function do_change_password(e) {
        e.preventDefault();
        e.stopPropagation();
        const change_password_error = $("#change_password_modal").find("#dialog_error");
        change_password_error.hide();

        const data = {
            old_password: $("#old_password").val(),
            new_password: $("#new_password").val(),
